// #6a993d795019333734edc22d (#edc22d) AC4 — не Super Admin: экраны управления бизнесами закрыты, данных нет (кейс BIZ-LC-007).
// Только чтение — @prod-safe. Пустой вызов admin-create-business ничего не создаёт (403 до проверки полей).
import { test, expect } from '../../fixtures';
import { SUPABASE_URL, openWithApi } from '../support/api';

test.describe('Управление бизнесами — отказ не-Super Admin (#6a993d795019333734edc22d)', () => {
  test('business и user: /admin/businesses, /new, /<id> — «קוד 403», ни одного бизнеса; RPC и создание → 403 @desktop @prod-safe #6a993d795019333734edc22d', async ({ asUser }) => {
    // Чужой бизнес (не свой у business/user) — из списка Super Admin.
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, '/admin/businesses');
    const listRes = await adminApi.rpc('admin_list_businesses');
    expect(listRes.status()).toBe(200);
    const all = (await listRes.json()) as { id: string; name: string }[];

    for (const role of ['business', 'user'] as const) {
      const page = await asUser(role);
      const api = await openWithApi(page, '/admin/businesses');
      const own = (await (await api.get('businesses?select=id')).json()) as { id: string }[];
      const other = all.find((b) => !own.some((o) => o.id === b.id));
      expect(other, 'нужен хотя бы один чужой бизнес').toBeTruthy();

      for (const url of ['/admin/businesses', '/admin/businesses/new', `/admin/businesses/${other!.id}`]) {
        if (url !== '/admin/businesses') await page.goto(url);
        // AC4: «הגישה נדחית ולא מוצג לו מידע על עסק כלשהו».
        await expect(page.getByRole('heading', { level: 1, name: 'אין לכם גישה לעמוד הזה' }), `${role} ${url}`).toBeVisible();
        await expect(page.getByText('קוד 403')).toBeVisible();
        await expect(page.getByRole('table', { name: /^רשימת בתי העסק/ })).toHaveCount(0);
        await expect(page.getByRole('button', { name: 'יצירת בית העסק' })).toHaveCount(0);
        await expect(page.getByRole('main').getByText(other!.name, { exact: true })).toHaveCount(0);
      }

      const list = await api.rpc('admin_list_businesses');
      expect(list.status(), `${role}: admin_list_businesses`).toBe(403);
      expect(await list.text()).toContain('forbidden');
      const get = await api.rpc('admin_get_business', { p_business_id: other!.id });
      expect(get.status(), `${role}: admin_get_business`).toBe(403);
      expect(await get.text()).not.toContain(other!.name);
      const create = await page.request.post(`${SUPABASE_URL}/functions/v1/admin-create-business`, { headers: api.headers, data: {} });
      expect(create.status(), `${role}: admin-create-business`).toBe(403);
    }
  });
});
